    +'.hmap .mk[data-state=watch] .pin,.hmap .mk[data-state=attention] .pin{width:9px;height:9px;opacity:1;background:#fff;box-shadow:0 0 0 2px var(--c),0 0 12px 2px color-mix(in srgb,var(--c) 70%,transparent)}'
